SET search_path TO itembaz, public;
INSERT INTO permissions(code,description) VALUES ('settings.read','View legal-company configuration and numbering'),('settings.manage','Create and submit configuration versions'),('settings.approve','Independently activate, reject, or retire configuration'),('settings.numbering.manage','Create controlled document number sequences'),('settings.numbering.allocate','Atomically allocate document numbers');
CREATE TABLE configuration_versions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,category text NOT NULL CHECK(category IN('SALES','PURCHASING','INVENTORY','FINANCE','HR','NUMBERING','TEMPLATES','NOTIFICATIONS','IMPORTS','INTEGRATIONS')),config_key text NOT NULL,name_en text NOT NULL,name_sw text NOT NULL,value jsonb NOT NULL CHECK(jsonb_typeof(value)='object'),secret_ref text NOT NULL DEFAULT '',effective_from date NOT NULL,effective_to date,status text NOT NULL CHECK(status IN('DRAFT','SUBMITTED','ACTIVE','REJECTED','RETIRED')),reason text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL,approved_by uuid,approved_at timestamptz,UNIQUE(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,category,config_key,effective_from),FOREIGN KEY(tenant_id,company_id) REFERENCES legal_companies(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,approved_by) REFERENCES users(tenant_id,id));
CREATE TABLE configuration_transitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,company_id uuid NOT NULL,configuration_id uuid NOT NULL,from_status text NOT NULL,to_status text NOT NULL,reason text NOT NULL,actor_id uuid NOT NULL,occurred_at timestamptz NOT NULL,FOREIGN KEY(tenant_id,company_id,configuration_id) REFERENCES configuration_versions(tenant_id,company_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id));
CREATE TABLE number_sequences(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,sequence_key text NOT NULL,prefix text NOT NULL,next_value bigint NOT NULL CHECK(next_value>0),padding bigint NOT NULL CHECK(padding BETWEEN 1 AND 18),created_by uuid NOT NULL,created_at timestamptz NOT NULL,UNIQUE(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,sequence_key),FOREIGN KEY(tenant_id,company_id) REFERENCES legal_companies(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES users(tenant_id,id));
CREATE TABLE number_allocations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,sequence_id uuid NOT NULL,allocated_value bigint NOT NULL,allocated_number text NOT NULL,allocated_by uuid NOT NULL,allocated_at timestamptz NOT NULL,UNIQUE(tenant_id,company_id,sequence_id,allocated_value),UNIQUE(tenant_id,company_id,allocated_number),FOREIGN KEY(tenant_id,company_id,sequence_id) REFERENCES number_sequences(tenant_id,company_id,id),FOREIGN KEY(tenant_id,allocated_by) REFERENCES users(tenant_id,id));
CREATE INDEX configuration_scope_key ON configuration_versions(tenant_id,company_id,category,config_key,status,effective_from); CREATE INDEX numbering_scope_key ON number_sequences(tenant_id,company_id,sequence_key);
CREATE FUNCTION protect_configuration() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'configuration cannot be deleted' USING ERRCODE='55000'; END IF; IF to_jsonb(NEW)-ARRAY['status','approved_by','approved_at']<>to_jsonb(OLD)-ARRAY['status','approved_by','approved_at'] THEN RAISE EXCEPTION 'configuration facts are immutable' USING ERRCODE='55000'; END IF; RETURN NEW; END $$;
CREATE TRIGGER configuration_guard BEFORE UPDATE OR DELETE ON configuration_versions FOR EACH ROW EXECUTE FUNCTION protect_configuration(); CREATE TRIGGER configuration_transitions_guard BEFORE UPDATE OR DELETE ON configuration_transitions FOR EACH ROW EXECUTE FUNCTION reject_mutation(); CREATE TRIGGER number_allocations_guard BEFORE UPDATE OR DELETE ON number_allocations FOR EACH ROW EXECUTE FUNCTION reject_mutation();
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['configuration_versions','configuration_transitions','number_sequences','number_allocations'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',n);END LOOP;END $$;
REVOKE ALL ON configuration_versions,configuration_transitions,number_sequences,number_allocations FROM PUBLIC,itembaz_worker_runtime;GRANT SELECT,INSERT,UPDATE ON configuration_versions,number_sequences TO itembaz_runtime;GRANT SELECT,INSERT ON configuration_transitions,number_allocations TO itembaz_runtime;
